  ctx.strokeStyle='#e5ebf4';ctx.beginPath();ctx.moveTo(38,779);ctx.lineTo(557,779);ctx.stroke();text('Simple cash tracking. No currency conversion, tax or stock adjustments.',38,797,7,'#8b98aa');text(`Page ${p+1} of ${count}`,557,797,8,'#8b98aa',false,'right');
